begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id,email_confirmed_at) values (md5('continuity_a')::uuid,clock_timestamp()),(md5('continuity_b')::uuid,clock_timestamp());
insert into public.profiles(id,display_name) values(md5('continuity_a')::uuid,'A'),(md5('continuity_b')::uuid,'B');
select ok(not has_function_privilege('anon','public.workout_continuity(uuid,uuid)','execute'),'anonymous continuity denied');
select ok(not has_function_privilege('service_role','public.workout_continuity(uuid,uuid)','execute'),'no service shortcut');
select ok((select bool_and(not prosecdef) from pg_proc where proname in('workout_continuity','end_workout','manage_workout_continuity','touch_workout_activity')),'continuity uses invoker RLS');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('continuity_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.w',public.start_ad_hoc_workout()::text,true);
select ok((select last_activity_at>=started_at and activity_evidence_at is null and not recognition_enabled from workout_sessions where id=current_setting('body_test.w')::uuid),'start initializes server time without activity evidence');
select throws_ok($$update workout_sessions set last_activity_at=now()+interval '1 year' where id=current_setting('body_test.w')::uuid$$,'42501',null,'cannot submit activity time');
select throws_ok($$update workout_sessions set started_at=now() where id=current_setting('body_test.w')::uuid$$,'42501',null,'cannot submit start time');
select throws_ok($$update workout_sessions set finished_at=now() where id=current_setting('body_test.w')::uuid$$,'42501',null,'cannot submit finish time');
select throws_ok($$update workout_sessions set recognition_enabled=true where id=current_setting('body_test.w')::uuid$$,'42501',null,'cannot forge recognition');
select set_config('body_test.passive',(select last_activity_at::text from workout_sessions where id=current_setting('body_test.w')::uuid),true);
select is(public.workout_continuity()->>'state','active','new workout active');
select is((select last_activity_at::text from workout_sessions where id=current_setting('body_test.w')::uuid),current_setting('body_test.passive'),'passive read never extends activity');
select set_config('body_test.e',public.edit_workout(current_setting('body_test.w')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select ok((select activity_evidence_at is not null and last_activity_at>current_setting('body_test.passive')::timestamptz from workout_sessions where id=current_setting('body_test.w')::uuid),'successful selection and pending structure touch atomically');
select set_config('body_test.passive',(select last_activity_at::text from workout_sessions where id=current_setting('body_test.w')::uuid),true);
select throws_ok($$select public.log_workout_set(current_setting('body_test.e')::uuid,(select id from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid order by position limit 1),'save',999,md5('bad_revision')::uuid,5,50,'working','external',true)$$,'40001',null,'failed CAS rejected');
select is((select last_activity_at::text from workout_sessions where id=current_setting('body_test.w')::uuid),current_setting('body_test.passive'),'failed mutation does not touch');
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '2 hours',last_activity_at=clock_timestamp()-interval '29 minutes 59 seconds' where id=current_setting('body_test.w')::uuid;
set local role authenticated;
select is(public.workout_continuity()->>'state','active','under 30 minutes active');
reset role;
update workout_sessions set last_activity_at=clock_timestamp()-interval '30 minutes' where id=current_setting('body_test.w')::uuid;
set local role authenticated;
select is(public.workout_continuity()->>'state','quiet','30 minutes noninterrupting quiet');
reset role;
update workout_sessions set last_activity_at=clock_timestamp()-interval '59 minutes 59 seconds' where id=current_setting('body_test.w')::uuid;
set local role authenticated;
select is(public.workout_continuity()->>'state','quiet','under 60 still quiet');
reset role;
update workout_sessions set last_activity_at=clock_timestamp()-interval '60 minutes' where id=current_setting('body_test.w')::uuid;
set local role authenticated;
select is(public.workout_continuity()->>'state','check_in','60 minute boundary check-in');
select is(public.workout_continuity(current_setting('body_test.w')::uuid,md5('resume_1')::uuid)->>'state','active','explicit continuation resumes same workout');
select is((select continuation_count from workout_sessions where id=current_setting('body_test.w')::uuid),1,'one continuation event');
select is((select jsonb_array_length(idle_intervals) from workout_sessions where id=current_setting('body_test.w')::uuid),1,'structured gap retained');
select set_config('body_test.passive',(select last_activity_at::text from workout_sessions where id=current_setting('body_test.w')::uuid),true);
select is((public.workout_continuity(current_setting('body_test.w')::uuid,md5('resume_1')::uuid)->>'last_activity_at')::timestamptz,current_setting('body_test.passive')::timestamptz,'resume retry idempotent');
select is((select continuation_count from workout_sessions where id=current_setting('body_test.w')::uuid),1,'retry does not duplicate events');
select set_config('request.jwt.claims',json_build_object('sub',md5('continuity_b')::uuid,'role','authenticated')::text,true);
select is(public.workout_continuity(current_setting('body_test.w')::uuid),null::jsonb,'foreign continuity hidden');
select throws_ok($$select public.end_workout(current_setting('body_test.w')::uuid,'completed')$$,'42501',null,'foreign close denied');
select set_config('request.jwt.claims',json_build_object('sub',md5('continuity_a')::uuid,'role','authenticated')::text,true);
reset role;
update workout_sessions set last_activity_at=clock_timestamp()-interval '90 minutes',activity_evidence_at=clock_timestamp()-interval '90 minutes' where id=current_setting('body_test.w')::uuid;
set local role authenticated;
select is(public.end_workout(current_setting('body_test.w')::uuid,'completed'),current_setting('body_test.w')::uuid,'check-in finish successful');
select ok((select effective_finished_at=last_activity_at and finished_at>effective_finished_at and duration_kind='estimated' and recognition_enabled from workout_sessions where id=current_setting('body_test.w')::uuid),'historical estimate separate from administrative finish');
select set_config('body_test.finish',(select finished_at::text from workout_sessions where id=current_setting('body_test.w')::uuid),true);
select is(public.end_workout(current_setting('body_test.w')::uuid,'completed'),current_setting('body_test.w')::uuid,'finish retry idempotent');
select is((select finished_at::text from workout_sessions where id=current_setting('body_test.w')::uuid),current_setting('body_test.finish'),'retry preserves finish');
select throws_ok($$update workout_sessions set name='reopened' where id=current_setting('body_test.w')::uuid$$,'23514',null,'closed metadata immutable');
select set_config('body_test.normal',public.start_ad_hoc_workout()::text,true);
select is(public.end_workout(current_setting('body_test.normal')::uuid,'completed'),current_setting('body_test.normal')::uuid,'ordinary finish successful');
select ok((select effective_finished_at=finished_at and duration_kind='elapsed' from workout_sessions where id=current_setting('body_test.normal')::uuid),'normal finish uses actual finish');
select set_config('body_test.expired',public.start_ad_hoc_workout()::text,true);
select set_config('body_test.ee',public.edit_workout(current_setting('body_test.expired')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select lives_ok($$select public.log_workout_set(current_setting('body_test.ee')::uuid,(select id from workout_sets where workout_exercise_id=current_setting('body_test.ee')::uuid order by position limit 1),'save',0,md5('good_set')::uuid,5,50,'working','external',true)$$,'saved completed set');
select set_config('body_test.set_time',(select completed_at::text from workout_sets where workout_exercise_id=current_setting('body_test.ee')::uuid and status='completed'),true);
select lives_ok($$update workout_sets set completed_at='2099-01-01' where workout_exercise_id=current_setting('body_test.ee')::uuid and status='completed'$$,'direct completion timestamp proposal is safely ignored');
select is((select completed_at::text from workout_sets where workout_exercise_id=current_setting('body_test.ee')::uuid and status='completed'),current_setting('body_test.set_time'),'client cannot backdate or move existing performance event');
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '14 hours',last_activity_at=clock_timestamp()-interval '12 hours',activity_evidence_at=clock_timestamp()-interval '12 hours' where id=current_setting('body_test.expired')::uuid;
set local role authenticated;
select is((select count(*)::int from public.log_workout_set(current_setting('body_test.ee')::uuid,(select id from workout_sets where workout_exercise_id=current_setting('body_test.ee')::uuid order by position limit 1),'save',1,md5('stale_write')::uuid,99,999,'working','external',true)),0,'expired mutation returns committed rejection without overwriting saved set');
select ok((select status='abandoned' and closure_reason='inactivity' and not recognition_enabled and effective_finished_at=last_activity_at from workout_sessions where id=current_setting('body_test.expired')::uuid),'12 hour boundary server-abandoned with audit metadata');
select is((select actual_reps from workout_sets where workout_exercise_id=current_setting('body_test.ee')::uuid order by position limit 1),5,'completed performance preserved');
select is((select count(*)::int from workout_sets where workout_exercise_id=current_setting('body_test.ee')::uuid and status='pending'),2,'pending sets not fabricated/deleted');
select is(public.workout_continuity(current_setting('body_test.expired')::uuid)->>'state','expired','repeated expiration remains expired');
select is(public.end_workout(current_setting('body_test.expired')::uuid,'completed'),null::uuid,'expired finish cannot convert to completed');
select is(public.workout_continuity(current_setting('body_test.expired')::uuid,md5('late_resume')::uuid)->>'state','expired','12 hour workout cannot resume');
select isnt(public.start_ad_hoc_workout(),current_setting('body_test.expired')::uuid,'expiration releases unique active slot');
select lives_ok($$select public.end_workout((select id from workout_sessions where status='in_progress'),'abandoned')$$,'close remaining active');
select set_config('body_test.empty',public.start_ad_hoc_workout()::text,true);
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '2 hours',last_activity_at=clock_timestamp()-interval '90 minutes' where id=current_setting('body_test.empty')::uuid;
set local role authenticated;
select lives_ok($$select public.end_workout(current_setting('body_test.empty')::uuid,'completed')$$,'empty stale session may close');
select ok((select duration_kind='unknown' and effective_finished_at is null from workout_sessions where id=current_setting('body_test.empty')::uuid),'no activity evidence means no duration estimate');
reset role;
insert into workout_sessions(id,owner_id,name,status,started_at,finished_at) values(md5('legacy_closed')::uuid,md5('continuity_a')::uuid,'Old','completed','2020-01-01','2020-01-02');
insert into workout_sessions(id,owner_id,name,started_at) values(md5('legacy_active')::uuid,md5('continuity_a')::uuid,'Old active','2020-01-01');
set local role authenticated;
select ok((select last_activity_at is null and effective_finished_at is null and duration_kind='legacy' and not recognition_enabled from workout_sessions where id=md5('legacy_closed')::uuid),'old history never backfilled with invented metadata');
select is(public.workout_continuity(md5('legacy_active')::uuid)->>'state','check_in','unknown legacy activity is not invented for expiration');
select is(public.workout_continuity(md5('legacy_active')::uuid,md5('legacy_resume')::uuid)->>'state','active','legacy active can deliberately resume');
select ok((select idle_intervals->0->>'legacy_unknown'='true' and activity_evidence_at is null from workout_sessions where id=md5('legacy_active')::uuid),'unknown gap recorded without evidence invention');
reset role;
insert into workout_sessions(id,owner_id,name,status,started_at,finished_at,closure_reason,duration_kind) values(md5('older_expiry_notice')::uuid,md5('continuity_b')::uuid,'Expired','abandoned','2020-01-01','2020-01-02','inactivity','unknown');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('continuity_b')::uuid,'role','authenticated')::text,true);
select is(public.workout_continuity()->>'id',(md5('older_expiry_notice')::uuid)::text,'next return retains expiration explanation even after more than a day');
select * from finish();rollback;
